SELECT id, user_id, title, start_date, end_date, region, theme, status, created_at
FROM trips
WHERE id = #{id}

SELECT id, user_id, title, start_date, end_date, region, theme, status, created_at
FROM trips
WHERE user_id = #{userId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT COUNT(*)
FROM trips
WHERE user_id = #{userId}
